def scan_rc_local():
    rc_files = ['/etc/rc.local', '/etc/rc.d/rc.local']
    if os.path.exists('/app_target'):
        for r, dirs, files in os.walk('/app_target'):
            for f in files:
                if f == 'rc.local':
                    rc_files.append(os.path.join(r, f))

    for raw_path in rc_files:
        real_path = resolve_path(raw_path)
        if not os.path.isfile(real_path):
            continue

        sha256 = get_sha256(real_path)
        if not sha256:
            continue

        try:
            with open(real_path, 'r', errors='ignore') as f:
                for line_num, line in enumerate(f, 1):
                    line_str = line.strip()
                    if not line_str or line_str.startswith('#'):
                        continue
                    if line_str.startswith('#!') or line_str in ['exit 0', 'exit 1']:
                        continue

                    key = (real_path, line_num)
                    if key in scanned_rc_lines:
                        continue

                    scanned_rc_lines.add(key)
                    artifacts.append({
                        'type': 'rc_local',
                        'path': real_path,
                        'sha256': sha256,
                        'details': {
                            'line_number': line_num,
                            'content_preview': line_str[:100],
                            'user': None
                        }
